package owl.nh;

import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.*;import net.runelite.client.callback.ClientThread;

public final class AdminZoomControllerTests {
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{AtomicInteger distance=new AtomicInteger(25);Scene scene=(Scene)Proxy.newProxyInstance(Scene.class.getClassLoader(),new Class[]{Scene.class},(o,m,a)->{if(m.getName().equals("getDrawDistance"))return distance.get();if(m.getName().equals("setDrawDistance")){distance.set((Integer)a[0]);return null;}return defaultValue(m.getReturnType());});Map<Integer,Integer> varcs=new HashMap<>();varcs.put(VarClientInt.CAMERA_ZOOM_FIXED_VIEWPORT,512);varcs.put(VarClientInt.CAMERA_ZOOM_RESIZABLE_VIEWPORT,600);AtomicInteger scripts=new AtomicInteger();Client client=(Client)Proxy.newProxyInstance(Client.class.getClassLoader(),new Class[]{Client.class},(o,m,a)->{switch(m.getName()){case "getGameState":return GameState.LOGGED_IN;case "getScene":return scene;case "isClientThread":return true;case "getVarcIntValue":return varcs.getOrDefault((Integer)a[0],0);case "setVarcIntValue":varcs.put((Integer)a[0],(Integer)a[1]);return null;case "runScript":scripts.incrementAndGet();return null;case "equals":return o==a[0];case "hashCode":return System.identityHashCode(o);default:return defaultValue(m.getReturnType());}});Constructor<ClientThread> ctor=ClientThread.class.getDeclaredConstructor(Client.class);ctor.setAccessible(true);AdminZoomController zoom=new AdminZoomController(client,ctor.newInstance(client));zoom.enable();check(distance.get()==AdminZoomController.EXTENDED_DRAW_DISTANCE,"admin zoom applies");zoom.pulse();check(scripts.get()==1,"zoom is not reset each tick");zoom.disable();check(distance.get()==25&&varcs.get(VarClientInt.CAMERA_ZOOM_FIXED_VIEWPORT)==512,"camera state restores");System.out.println("Admin zoom checks passed.");}
 static Object defaultValue(Class<?> type){if(type==boolean.class)return false;if(type==int.class)return 0;if(type==long.class)return 0L;return null;}
}
